from PyQt5 import QtWidgets,uic  #☻
from numpy import *

def verif(x):
    if x.isnumeric() and len(x) != 0 :
        if 2 <= int(x) <= 100 :
            return True
        else :
            return False
    else :
        return False

def multiplication():
    a=p.t1.text()
    b=p.t2.text()
    if verif(a) and verif(b):
        a=int(a)
        b=int(b)
        DV=array([0]*(a+b))
        MLT=array([0]*(a+b))
        i = 0
        while a != 0 :
            DV[i]=a
            MLT[i]=b
            a = a // 2
            b = b * 2
            i += 1
        ch = 0
        for j in range (i):
            if DV[j] % 2 == 1 :
                ch += (MLT[j])
        p.t3.setText(str(ch))
    else :
        p.t3.setText("INPUT ERROR")
